<script lang="ts">
	import type { Snippet, Component } from "svelte";
	import Close from "./Close.svelte";
	import Icon from "./Icon.svelte";
	import { removeToast } from "./toasts.svelte.js";

	/**
	 * @description
	 * A styled toast/notification card. Uses the shared surface styling system (background, border, shadow).
	 * Typically created via `addToast()` but can be used standalone. Automatically adapts its grid layout
	 * based on whether an icon and/or actions are present.
	 * @example
	 * <Toast title="Saved" content="Your changes have been saved." />
	 */
	let {
		id,
		children,
		title,
		content,
		icon,
		actions,
		onclose,
	}: {
		/** Unique ID for the toast (used by removeToast) */
		id?: string;
		/** Custom content snippet */
		children?: Snippet;
		/** Toast title */
		title?: string;
		/** Toast content text */
		content?: string;
		/** Icon (name or component) */
		icon?: string | Component;
		/** Action buttons snippet */
		actions?: Snippet;
		/** Called when close button is clicked */
		onclose?: () => void;
	} = $props();

	function handleClose() {
		if (id) {
			removeToast(id);
		}
		onclose?.();
	}
</script>

<div class="Toast">
	{#if !actions}
		<Close position="top right" onclick={handleClose} />
	{/if}
	
	{#if icon}
		<div class="Icon">
			<Icon {icon} />
		</div>
	{/if}
	
	<div class="Content">
		{#if title}
			<h5 class="Title">{title}</h5>
		{/if}
		{#if content}
			<p class="Text">{content}</p>
		{/if}
		{#if children}
			{@render children()}
		{/if}
	</div>
	
	{#if actions}
		<div class="Actions">
			{@render actions()}
		</div>
	{/if}
</div>

<style>
	.Toast {
		position: relative;
		display: grid;
		grid-template-columns: 1fr;
		gap: var(--toast-gap, var(--space-sm));
		background: var(--toast-background, var(--surface-background));
		border: var(--toast-border, var(--surface-border));
		border-radius: var(--toast-border-radius, var(--surface-border-radius));
		box-shadow: var(--toast-shadow, var(--surface-shadow));
		padding-block: var(--toast-padding-block, var(--space-md));
		padding-inline: var(--toast-padding-inline, var(--space-lg));
		min-width: var(--toast-min-width, 20rem);
		max-width: var(--toast-max-width, 28rem);
		animation: toast-enter 0.2s ease-out;
	}

	@media (prefers-reduced-motion: reduce) {
		.Toast {
			animation: none;
		}
	}

	.Toast:has(> .Icon) {
		grid-template-columns: auto 1fr;
	}

	.Toast:has(> .Actions) {
		grid-template-columns: 1fr auto;
	}

	.Toast:has(> .Icon):has(> .Actions) {
		grid-template-columns: auto 1fr auto;
	}

	.Icon {
		display: flex;
		align-items: flex-start;
		font-size: var(--toast-icon-size, 1.25rem);
		color: var(--text-color-p-subtle);
	}

	.Content {
		display: flex;
		flex-direction: column;
		gap: var(--space-xs);
	}

	.Title {
		font-weight: var(--toast-title-font-weight, var(--font-weight-semibold));
		color: var(--toast-title-color, var(--text-color-heading));
		line-height: 1.3;
	}

	.Text {
		margin: 0;
		color: var(--toast-text-color, var(--text-color-p-subtle));
		line-height: 1.4;
	}

	.Actions {
		display: flex;
		align-items: center;
		gap: var(--space-xs);
	}
</style>
